WITH unpacked AS (SELECT id, currency, tier_prices, SLICE(tier_limits, 1, 2) AS first_two_limits, ARRAY_MIN(tier_prices) AS lowest_price, AGGREGATE(tier_prices, CAST(0 AS DOUBLE), (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, ELEMENT_AT(tier_prices, 1) AS entry_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps FROM price_tiers) SELECT id, lowest_price, avg_tier_price, LAG(avg_tier_price, 1) OVER (PARTITION BY currency ORDER BY avg_tier_price, id) AS prev_avg_tier_price, ROW_NUMBER() OVER w_part AS seq_no FROM unpacked WINDOW w_part AS (PARTITION BY currency ORDER BY entry_price DESC, id);
